import { describe, expect, it } from 'vitest';
import { createR2MediaSource } from '../src/services/media/r2-mediabunny-source';
import { assertRemuxableSource, assertRemuxableVideoCodec } from '../src/services/media/r2-remux';

const H264_MP4 = '';

function decodeBase64(value: string) {
  const binary = atob(value);
  const bytes = new Uint8Array(binary.length);
  for (let index = 0; index < binary.length; index += 1) {
    bytes[index] = binary.charCodeAt(index);
  }
  return bytes;
}

function bucketFor(bytes: Uint8Array) {
  return {
    async head(key: string) { return { key, size: bytes.byteLength }; },
    async get(key: string, options?: { range?: { offset: number; length: number } }) {
      const range = options?.range ?? { offset: 0, length: bytes.byteLength };
      return {
        key,
        size: bytes.byteLength,
        body: new ReadableStream<Uint8Array>({
          start(controller) {
            controller.enqueue(bytes.slice(range.offset, range.offset + range.length));
            controller.close();
          },
        }),
      };
    },
  };
}

describe('R2 remux admission', () => {
  it('admits a readable H.264/AVC MP4 copy path without decoding video', async () => {
    const bytes = decodeBase64(H264_MP4);
    const source = await createR2MediaSource(bucketFor(bytes) as never, 'source.mp4');

    await expect(assertRemuxableSource(source)).resolves.toEqual({
      codec: 'avc',
      durationSeconds: 1,
    });
  });

  it('fails closed for video codecs that would require transcoding', () => {
    expect(() => assertRemuxableVideoCodec('hevc')).toThrow(/VIDEO_TRANSCODE_REQUIRED/);
  });
});
